(()=>{
const el=id=>document.getElementById(id);let source=null,result=null,synthBlob=null,originalURL=null,synthURL=null,worker=null,rejectWorker=null,workerTimer=0,busy=false,version=0,sectionEnd=null,captureActive=false,captureToken=0,captureTimer=0;
const original=el('vowelOriginal'),synth=el('vowelSynthAudio'),status=el('vowelStatus');
function stopComparison(){original.pause();synth.pause();sectionEnd=null;}
function controls(){el('vowelAnalyze').disabled=busy||captureActive||!source;el('vowelRecord').disabled=busy;el('vowelUseMic').disabled=busy||captureActive||!window.HarmonicMic?.getRecording();el('vowelAutoSection').disabled=busy;el('vowelStart').disabled=busy||el('vowelAutoSection').checked;el('vowelEnd').disabled=busy||el('vowelAutoSection').checked;el('vowelPitchMode').disabled=busy;el('vowelTarget').disabled=busy||el('vowelPitchMode').value!=='custom';el('vowelCancel').hidden=!busy;}
function invalidate(){version++;clearTimeout(workerTimer);if(worker){worker.terminate();worker=null;rejectWorker?.(new Error('Analysis cancelled.'));rejectWorker=null}stopComparison();result=null;synthBlob=null;el('vowelResult').hidden=true;if(synthURL)URL.revokeObjectURL(synthURL);synthURL=null;synth.removeAttribute('src');}
function drawSource(){const canvas=el('vowelSourceWave'),r=canvas.getBoundingClientRect(),d=devicePixelRatio||1,w=r.width||600,h=130;canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);const c=canvas.getContext('2d');c.scale(d,d);c.fillStyle='#9da9b7';c.font='11px system-ui';if(!source){c.fillText('Record a vowel to see its waveform.',16,30);return}const L=15,R=15,T=10,B=25,pw=w-L-R,ph=h-T-B,peak=Math.max(.001,...source.peaks);if(result){const a=result.segment.start/source.duration,b=result.segment.end/source.duration;c.fillStyle='#b9ed8125';c.fillRect(L+pw*a,T,pw*(b-a),ph)}c.strokeStyle='#7cbbef';c.beginPath();for(let x=0;x<pw;x++){const begin=Math.floor(x/pw*source.samples.length),end=Math.max(begin+1,Math.floor((x+1)/pw*source.samples.length));let low=0,high=0;for(let i=begin;i<end;i++){low=Math.min(low,source.samples[i]||0);high=Math.max(high,source.samples[i]||0)}c.moveTo(L+x,T+ph/2-low/peak*ph/2);c.lineTo(L+x,T+ph/2-high/peak*ph/2)}c.stroke();c.fillStyle='#9da9b7';c.fillText('0 s',L,h-7);c.fillText(source.duration.toFixed(2)+' s',w-65,h-7);if(result)c.fillText('Highlighted: analyzed section',L+45,h-7)}
async function load(blob,name){invalidate();const request=version;busy=true;source=null;controls();if(originalURL)URL.revokeObjectURL(originalURL);originalURL=null;original.hidden=true;original.removeAttribute('src');el('vowelSource').textContent='Loading recording…';status.textContent='Decoding audio locally…';try{const Offline=window.OfflineAudioContext||window.webkitOfflineAudioContext;if(!Offline)throw new Error('This browser cannot decode audio for analysis. Try a current desktop browser.');const decoder=new Offline(1,1,16000),buffer=await decoder.decodeAudioData(await blob.arrayBuffer());if(request!==version)return;if(buffer.duration>30||buffer.duration<.3)throw new Error('Record a vowel between 0.3 and 30 seconds long.');const samples=new Float32Array(buffer.length);for(let ch=0;ch<buffer.numberOfChannels;ch++){const data=buffer.getChannelData(ch);for(let i=0;i<samples.length;i++)samples[i]+=data[i]/buffer.numberOfChannels}const peaks=[];for(let i=0;i<samples.length;i+=256){let p=0;for(let j=i;j<Math.min(samples.length,i+256);j++)p=Math.max(p,Math.abs(samples[j]));peaks.push(p)}source={blob,name,samples,peaks,duration:buffer.duration,sampleRate:16000};originalURL=URL.createObjectURL(blob);original.src=originalURL;original.hidden=false;el('vowelStart').value=0;el('vowelEnd').value=buffer.duration.toFixed(2);el('vowelSource').textContent=`Loaded ${name} · ${buffer.duration.toFixed(2)} seconds · analyzed locally`;status.textContent='Ready. Press Analyze & synthesize to estimate the pitch and fill your sliders.';drawSource();}catch(error){if(request!==version)return;el('vowelSource').textContent='No microphone recording loaded.';status.textContent=error.message;drawSource();}finally{if(request===version){busy=false;controls()}}}
function analyzeWorker(samples,options){return new Promise((resolve,reject)=>{rejectWorker=reject;worker=new Worker('vowel-worker.js');const timer=workerTimer=setTimeout(()=>{worker?.terminate();worker=null;rejectWorker=null;reject(new Error('Analysis took too long. Try a shorter recording.'))},45000);const done=()=>{clearTimeout(timer);worker?.terminate();worker=null;rejectWorker=null};worker.onmessage=event=>{done();if(event.data.error)reject(new Error(event.data.error));else resolve(event.data.result)};worker.onerror=()=>{done();reject(new Error('The local analysis worker could not run. Refresh the page or try another browser.'))};worker.postMessage({samples,sampleRate:16000,options});})}
function table(){el('vowelHarmonics').replaceChildren();result.tones.forEach((tone,i)=>{const tr=document.createElement('tr');['H'+(i+1),tone.f.toFixed(1),tone.a.toFixed(3)].forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td)});el('vowelHarmonics').append(tr)})}
function stopCapture(){captureToken++;clearTimeout(captureTimer);captureActive=false;const hadRecording=window.HarmonicMic?.isRecording();window.HarmonicMic?.finishRecording();const blob=hadRecording?window.HarmonicMic.getRecording():null;window.HarmonicMic?.stop();el('vowelRecord').textContent='🎙 Record a vowel · 5 seconds';controls();if(blob)load(blob,'microphone-vowel.wav');else status.textContent='Recording cancelled or too short. Press Record to try again.';}
el('vowelRecord').onclick=async()=>{if(captureActive){stopCapture();return}stopComparison();HarmonicLab.stop();captureActive=true;const token=++captureToken;controls();el('vowelRecord').textContent='Cancel microphone request';status.textContent='Waiting for microphone permission…';try{const started=await window.HarmonicMic.start();if(token!==captureToken)return;if(!started){captureActive=false;el('vowelRecord').textContent='🎙 Record a vowel · 5 seconds';controls();status.textContent=el('micStatus').textContent;return}window.HarmonicMic.record();el('vowelRecord').textContent='■ Stop vowel recording';status.textContent='Recording your vowel… Hold it steadily. Stops after 5 seconds.';captureTimer=setTimeout(stopCapture,5000);}catch(error){if(token!==captureToken)return;captureActive=false;window.HarmonicMic?.stop();el('vowelRecord').textContent='🎙 Record a vowel · 5 seconds';controls();status.textContent=error.message||'Microphone could not start.';}};
el('vowelUseMic').onclick=()=>{window.HarmonicMic?.finishRecording();const blob=window.HarmonicMic?.getRecording();if(!blob){status.textContent='Finish a microphone recording first.';return}window.HarmonicMic.stop();load(blob,'microphone-vowel.wav')};window.addEventListener('harmonic-recording-ready',controls);
['vowelAutoSection','vowelPitchMode','vowelTarget','vowelStart','vowelEnd'].forEach(id=>el(id).onchange=()=>{invalidate();status.textContent=source?'Settings changed. Analyze again to update the reconstruction.':'Record a vowel to begin.';controls();drawSource()});
el('vowelAnalyze').onclick=async()=>{if(!source||busy)return;invalidate();const request=version;busy=true;controls();status.textContent='Analyzing repetition and harmonic strengths…';try{const options={auto:el('vowelAutoSection').checked,start:Number(el('vowelStart').value),end:Number(el('vowelEnd').value),target:el('vowelPitchMode').value,targetHz:Number(el('vowelTarget').value)},analysis=await analyzeWorker(source.samples,options);if(request!==version)return;status.textContent='Rendering a new vowel from the estimated harmonics…';const rendered=await HarmonicAudio.renderMix(analysis.tones,3,.3);if(request!==version)return;const output=rendered.getChannelData(0),a=Math.floor(analysis.segment.start*16000),b=Math.ceil(analysis.segment.end*16000);let originalEnergy=0,renderEnergy=0,peak=0;for(let i=a;i<b;i++)originalEnergy+=(source.samples[i]||0)**2;for(const v of output){renderEnergy+=v*v;peak=Math.max(peak,Math.abs(v))}const targetRms=Math.sqrt(originalEnergy/Math.max(1,b-a)),outputRms=Math.sqrt(renderEnergy/output.length),gain=Math.min(targetRms/(outputRms||1),.95/(peak||1));for(let i=0;i<output.length;i++)output[i]*=gain;result=analysis;synthBlob=HarmonicAudio.wav(output,rendered.sampleRate);synthURL=URL.createObjectURL(synthBlob);synth.src=synthURL;HarmonicLab.setTones(result.tones);el('vowelDetected').textContent=result.f0.toFixed(1)+' Hz';el('vowelSynthPitch').textContent=result.target.toFixed(1)+' Hz';el('vowelPeriodicity').textContent=(result.confidence*100).toFixed(0)+' / 100';el('vowelSectionInfo').textContent=`Section ${result.segment.start.toFixed(2)}–${result.segment.end.toFixed(2)} s · ${result.voicedFrames} voiced frames · 24 harmonic slots`;el('vowelStart').value=result.segment.start.toFixed(2);el('vowelEnd').value=result.segment.end.toFixed(2);el('vowelWarnings').textContent=result.warnings.join(' ');el('vowelWarnings').hidden=result.warnings.length===0;table();el('vowelResult').hidden=false;drawSource();status.textContent='Analysis complete. The main sliders now contain your vowel recipe. Compare the original section with the synthesized sound.';}catch(error){if(request===version)status.textContent=error.message||'Analysis failed. Try a different section.';}finally{if(request===version){busy=false;controls()}}};
el('vowelCancel').onclick=()=>{invalidate();busy=false;status.textContent='Analysis cancelled. Your recording is still loaded.';controls();drawSource()};
original.onplay=()=>{synth.pause();HarmonicLab.stop();window.HarmonicMic?.stop()};original.onpause=()=>{sectionEnd=null};original.ontimeupdate=()=>{if(sectionEnd!==null&&original.currentTime>=sectionEnd)original.pause()};synth.onplay=()=>{original.pause();HarmonicLab.stop();window.HarmonicMic?.stop()};
el('vowelPlayOriginal').onclick=async()=>{if(!result)return;stopComparison();original.currentTime=result.segment.start;sectionEnd=result.segment.end;try{await original.play()}catch{status.textContent='Press the original audio player to allow playback.'}};
el('vowelPlaySynth').onclick=async()=>{if(!result)return;stopComparison();synth.currentTime=0;try{await synth.play()}catch{status.textContent='Press the synthesized audio player to allow playback.'}};el('vowelStop').onclick=()=>{stopComparison();HarmonicLab.stop()};
el('vowelApply').onclick=()=>{if(result){HarmonicLab.setTones(result.tones);status.textContent='Restored the automatic recipe to the sliders.'}};
el('vowelDownloadOriginal').onclick=()=>{if(source)HarmonicAudio.download(source.blob,source.name)};el('vowelDownloadSynth').onclick=()=>{if(synthBlob)HarmonicAudio.download(synthBlob,'vowel-auto-synthesized.wav')};el('vowelDownloadSettings').onclick=()=>{if(result)HarmonicAudio.download(new Blob([JSON.stringify({method:'YIN-style pitch estimation and FFT harmonic-band analysis',source:source.name,...result},null,2)],{type:'application/json'}),'vowel-analysis.json')};
new ResizeObserver(drawSource).observe(el('vowelSourceWave'));window.addEventListener('pagehide',()=>{invalidate();if(originalURL)URL.revokeObjectURL(originalURL)});window.addEventListener('harmonic-synth-playing',stopComparison);document.addEventListener('visibilitychange',()=>{if(document.hidden){stopComparison();if(captureActive){captureToken++;clearTimeout(captureTimer);captureActive=false;el('vowelRecord').textContent='🎙 Record a vowel · 5 seconds';controls();status.textContent='Microphone stopped while the page was hidden. Use the latest recording or record again.';}}});controls();drawSource();
})();
